    /// <summary>
    /// Extract plain text from a PDF file using pdftotext with layout preservation.
    /// Returns empty string if pdftotext is not available.
    /// </summary>
    private static string ExtractText(string pdfPath)
    {
        var process = new Process
        {
            StartInfo = new ProcessStartInfo
            {
                FileName = "pdftotext",
                Arguments = $"-layout \"{pdfPath}\" -",
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            }
        };
        process.Start();
        string output = process.StandardOutput.ReadToEnd();
        process.WaitForExit();
        return output;
    }

    /// <summary>
    /// Extract PDF metadata (page count, page size) using pdfinfo.
    /// </summary>
    private static Dictionary<string, string> ExtractPdfInfo(string pdfPath)
    {
        var info = new Dictionary<string, string>();
        var process = new Process
        {
            StartInfo = new ProcessStartInfo
            {
                FileName = "pdfinfo",
                Arguments = $"\"{pdfPath}\"",
                RedirectStandardOutput = true,
                UseShellExecute = false,
                CreateNoWindow = true,
            }
        };
        process.Start();
        string output = process.StandardOutput.ReadToEnd();
        process.WaitForExit();

        foreach (string line in output.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            int colonIdx = line.IndexOf(':');
            if (colonIdx > 0)
            {
                string key = line[..colonIdx].Trim();
                string value = line[(colonIdx + 1)..].Trim();
                info[key] = value;
            }
        }
        return info;
    }

