    // ── Formatting helpers ────────────────────────────────────────────
    static string TruncateTo(string text, int maxLen)
    {
        if (string.IsNullOrEmpty(text)) return "";
        return text.Length <= maxLen ? text : text[..(maxLen - 3)] + "...";
    }

    static string FormatCnpj(string cnpj)
    {
        if (string.IsNullOrEmpty(cnpj) || cnpj.Length < 14) return cnpj;
        return $"{cnpj[..2]}.{cnpj[2..5]}.{cnpj[5..8]}/{cnpj[8..12]}-{cnpj[12..14]}";
    }

    static string FormatCpfCnpj(string doc)
    {
        if (string.IsNullOrEmpty(doc)) return "";
        string clean = doc.Replace(".", "").Replace("-", "").Replace("/", "");
        return clean.Length <= 11
            ? $"{clean[..3]}.{clean[3..6]}.{clean[6..9]}-{clean[9..11]}"
            : FormatCnpj(clean);
    }

    static string FormatDate(string isoDate)
    {
        if (string.IsNullOrEmpty(isoDate) || isoDate.Length < 10) return isoDate;
        return $"{isoDate[8..10]}/{isoDate[5..7]}/{isoDate[..4]}";
    }

    static string FormatTime(string isoDate)
    {
        if (string.IsNullOrEmpty(isoDate) || isoDate.Length < 19) return "";
        return isoDate[11..19];
    }

    static string FormatNfNumber(string nnf)
    {
        if (string.IsNullOrEmpty(nnf)) return "";
        return nnf.PadLeft(9, '0').Insert(3, ".").Insert(7, ".");
    }

    static string FormatChaveAcesso(string chave)
    {
        // Groups of 4 digits
        if (string.IsNullOrEmpty(chave) || chave.Length < 44) return chave;
        var parts = new List<string>();
        for (int i = 0; i < chave.Length; i += 4)
            parts.Add(chave[i..Math.Min(i + 4, chave.Length)]);
        return string.Join(" ", parts);
    }

    static string FormatCep(string cep)
    {
        if (string.IsNullOrEmpty(cep) || cep.Length < 8) return cep;
        return $"{cep[..5]}-{cep[5..8]}";
    }

    static string FormatIe(string ie)
    {
        if (string.IsNullOrEmpty(ie)) return "";
        if (ie.Length >= 9 && ie.All(char.IsDigit))
            return $"{ie[..3]}.{ie[3..6]}.{ie[6..]}";
        return ie;
    }

    static string FormatFone(string fone)
    {
        if (string.IsNullOrEmpty(fone)) return "";
        string clean = fone.Replace(" ", "").Replace("-", "").Replace(".", "");
        if (clean.Length == 10)
            return $"({clean[..2]}) {clean[2..6]}-{clean[6..]}";
        if (clean.Length == 11)
            return $"({clean[..2]}) {clean[2..7]}-{clean[7..]}";
        return fone;
    }

    static string FormatFrete(string modFrete)
    {
        return modFrete switch
        {
            "0" => "0 - Por conta do Emitente",
            "1" => "1 - Por conta do Destinatário",
            "2" => "2 - Por conta de Terceiros",
            _ => modFrete
        };
    }

