    [Fact]
    public void Validate_PdfInfo_Matches_Reference()
    {
        if (!File.Exists(ReferencePdfPath) || !File.Exists(XmlPath))
            return;

        // Arrange: generate DANFE
        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);
            Assert.True(File.Exists(generatedPath), "Generated PDF should exist");
            Assert.True(new FileInfo(generatedPath).Length > 0,
                "Generated PDF should not be empty");

            // Extract PDF metadata
            var refInfo = ExtractPdfInfo(ReferencePdfPath);
            var genInfo = ExtractPdfInfo(generatedPath);

            // Assert page count
            Assert.True(refInfo.ContainsKey("Pages"), "Reference PDF should have Pages info");
            string refPages = refInfo.GetValueOrDefault("Pages", "");
            string genPages = genInfo.GetValueOrDefault("Pages", "");
            Assert.Equal(refPages, genPages);

            // Assert page size (both A4)
            if (refInfo.TryGetValue("Page size", out var refPageSize))
            {
                Assert.True(genInfo.TryGetValue("Page size", out var genPageSize),
                    "Generated PDF should have Page size info");
                // Both should be approximately A4: 595 x 842 pts
                Assert.Contains("595", genPageSize);
                Assert.Contains("842", genPageSize);
            }
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }

    [Fact]
    public void Validate_Emitente_Data_Matches_Reference()
    {

        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);

            string refText = ExtractText(ReferencePdfPath);
            string genText = ExtractText(generatedPath);

            // ── Emitente name ─────────────────────────────────────────
            Assert.Contains("EMPRESA EXEMPLO LTDA", genText); // Generated PDF should contain emitente name

            // ── Emitente CNPJ (formatted) ─────────────────────────────
            string cnpjFormatted = FormatCnpj(data.EmitCnpj);
            Assert.Contains(cnpjFormatted, genText); // Generated PDF should contain CNPJ: {cnpjFormatted}

            // ── Emitente address ──────────────────────────────────────
            Assert.Contains(data.EmitXLogr, genText); // Generated PDF should contain address: {data.EmitXLogr}
            Assert.Contains(data.EmitXMun, genText); // Generated PDF should contain municipality: {data.EmitXMun}
            Assert.Contains(data.EmitUf, genText); // Generated PDF should contain UF: {data.EmitUf}

            // ── Emitente IE ───────────────────────────────────────────
            if (!string.IsNullOrEmpty(data.EmitIe))
            {
                Assert.Contains(FormatIe(data.EmitIe), genText); // Generated PDF should contain IE: {FormatIe(data.EmitIe)}
            }
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }

    [Fact]
    public void Validate_Destinatario_Data_Matches_Reference()
    {

        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);

            string genText = ExtractText(generatedPath);

            // ── Destinatário name ─────────────────────────────────────
            string destNome = "NF-E EMITIDA EM AMBIENTE DE HOMOLOGACAO";
            Assert.Contains(destNome, genText); // Generated PDF should contain destinatário name

            // ── Destinatário CNPJ ─────────────────────────────────────
            string destCnpj = FormatCpfCnpj(data.DestCnpj);
            Assert.Contains(destCnpj, genText); // Generated PDF should contain dest CNPJ: {destCnpj}

            // ── Destinatário address ──────────────────────────────────
            Assert.Contains(data.DestXLogr, genText); // Generated PDF should contain dest address: {data.DestXLogr}
            Assert.Contains(data.DestXBairro, genText); // Generated PDF should contain dest neighborhood: {data.DestXBairro}
            Assert.Contains(data.DestXMun, genText); // Generated PDF should contain dest municipality: {data.DestXMun}
            Assert.Contains(data.DestUf, genText); // Generated PDF should contain dest UF: {data.DestUf}

            // ── Data emissão formatted ────────────────────────────────
            string formattedDate = FormatDate(data.DhEmi);
            Assert.Contains(formattedDate, genText); // Generated PDF should contain emission date: {formattedDate}
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }

    [Fact]
    public void Validate_NFe_Identification_Matches_Reference()
    {

        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);

            string genText = ExtractText(generatedPath);

            // ── DANFE title ───────────────────────────────────────────
            Assert.Contains("DANFE", genText); // Generated PDF should contain DANFE title
            Assert.Contains("DOCUMENTO AUXILIAR", genText); // Generated PDF should contain DOCUMENTO AUXILIAR
            Assert.Contains("DA NOTA FISCAL", genText); // Generated PDF should contain DA NOTA FISCAL
            Assert.Contains("ELETRÔNICA", genText); // Generated PDF should contain ELETRÔNICA

            // ── Chave de acesso ───────────────────────────────────────
            Assert.Contains("CHAVE DE ACESSO", genText); // Generated PDF should contain CHAVE DE ACESSO section
            // Check first group of 4 digits
            Assert.Contains("2125", genText); // Generated PDF should contain first group of chave
            // Check last 4 digits
            Assert.Contains("4567", genText); // Generated PDF should contain last group of chave

            // ── NFe number and series ─────────────────────────────────
            Assert.Contains(data.Serie, genText); // Generated PDF should contain série: {data.Serie}

            // ── FOLHA ────────────────────────────────────────────────
            Assert.Contains("FOLHA 1/1", genText); // Generated PDF should contain FOLHA 1/1

            // ── Natureza da operação ──────────────────────────────────
            Assert.Contains("NATUREZA DA OPERAÇÃO", genText); // Generated PDF should contain NATUREZA DA OPERAÇÃO
            Assert.Contains("Compra", genText); // Generated PDF should contain natureza text

            // ── Protocolo data ─────────────────────────────────────────
            // (appears inline next to NATUREZA in reference layout)
            if (!string.IsNullOrEmpty(data.NProt))
            {
                Assert.Contains(data.NProt, genText);
            }
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }

