    [Fact]
    public void Validate_Layout_Sections_Present_In_Correct_Order()
    {

        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);

            string refText = ExtractText(ReferencePdfPath);
            string genText = ExtractText(generatedPath);

            // ── Ordered section titles that must appear ───────────────
            string[] requiredSections =
            [
                "DANFE",
                "CHAVE DE ACESSO",
                "NATUREZA DA OPERAÇÃO",
                "INSCRIÇÃO ESTADUAL",
                "DESTINATÁRIO / REMETENTE",
                "FATURA / DUPLICATAS",
                "CÁLCULO DO IMPOSTO",
                "TRANSPORTADOR / VOLUMES TRANSPORTADOS",
                "DADOS DO PRODUTO / SERVIÇO",
                "CÁLCULO DO ISSQN",
                "DADOS ADICIONAIS",
            ];

            // ── Verify each section appears in the text ───────────────
            foreach (string section in requiredSections)
            {
                Assert.Contains(section, genText); // Generated PDF must contain section: '{section}'
            }

            // ── Verify sections appear in correct order ───────────────
            // (index of each section in text must be increasing)
            int lastIndex = -1;
            foreach (string section in requiredSections)
            {
                int idx = genText.IndexOf(section, StringComparison.Ordinal);
                Assert.True(idx >= 0,
                    $"Section '{section}' should be present in generated PDF");
                Assert.True(idx > lastIndex,
                    $"Section '{section}' should appear after previous section. " +
                    $"Found at index {idx}, previous was at {lastIndex}.");
                lastIndex = idx;
            }

            // ── Footer disclaimer must be present ─────────────────────
            Assert.Contains("ambiente de homologação", genText); // Generated PDF should contain homologação disclaimer
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }

    [Fact]
    public void Validate_Barcode_Present()
    {
        if (!File.Exists(XmlPath))
            return;

        var data = new NFeParser().Parse(XmlPath);
        string generatedPath = Path.GetTempFileName() + ".pdf";

        try
        {
            GenerateEnhancedDanfe(data, generatedPath);

            // Read the PDF as text to check barcode stream exists
            string pdfContent = File.ReadAllText(generatedPath);

            // Code128 barcode should generate content streams
            // The barcode is rendered as filled rectangles (re operator in PDF)
            // Check for the barcode-related content
            Assert.Contains("CHAVE DE ACESSO", pdfContent); // PDF should contain CHAVE DE ACESSO text

            // Verify code128 barcode patterns are in the PDF stream
            // The barcode generates 're' (rectangle) operations
            Assert.Contains("re", pdfContent); // PDF should contain rectangle drawing operations (barcode)
        }
        finally
        {
            if (File.Exists(generatedPath)) File.Delete(generatedPath);
        }
    }
